unit WeakCycleDemo;

interface

type
  IParent = interface;
  IChild  = interface;

  IParent = interface
    ['{A4F6C3F8-0E6B-44C8-9B83-6F4D8E4A11DC}']
    function GetChild : IChild;
    procedure SetChild(const Value : IChild);
  end;

  IChild = interface
    ['{B5B2D49B-22D9-4D45-B3DD-2FF3A9F9F1A7}']
    function GetParent : IParent;
    procedure SetParent(const Value : IParent);
  end;

implementation

// No [weak] keyword on either side -> circular refcount.
// Parent.SetChild(Child); Child.SetParent(Parent);
// Both refcounts go to 1, both stay at 1 forever. Classic leak.

end.
